#include "string.h"
size_t strlen(const char *низ_данни) { const char *данни_позиция = низ_данни; while (*данни_позиция) данни_позиция++; return данни_позиция - низ_данни; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *x_координата = 첫째값, *세로좌표 = 둘째값; while (개수--) { if (*x_координата != *세로좌표) return (int)*x_координата - *세로좌표; x_координата++; 세로좌표++; } return 0; }
void *memmove(void *местоназначение_данни, const void *низ_данни, size_t 개수) { unsigned char *x_координата = местоназначение_данни; const unsigned char *세로좌표 = низ_данни; if (x_координата < 세로좌표) { for (size_t 순번 = 0; 순번 < 개수; 순번++) x_координата[순번] = 세로좌표[순번]; } else { while (개수) { 개수--; x_координата[개수] = 세로좌표[개수]; } } return местоназначение_данни; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char x_координата = *첫째값++, 세로좌표 = *둘째값++; if (x_координата != 세로좌표) return (int)x_координата-세로좌표; if (!x_координата) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *низ_данни, char **прекратяване_на_повикването_Изместване, int Фон_стойност) {
    const char *Старт_Изместване = низ_данни; unsigned long стойност = 0; int кодиране_стойност = 1, 하나라도 = 0;
    while (*низ_данни == ' ' || (*низ_данни >= 9 && *низ_данни <= 13)) низ_данни++;
    if (*низ_данни == '-' || *низ_данни == '+') { if (*низ_данни == '-') кодиране_стойност = -1; низ_данни++; }
    if (Фон_стойност == 0) Фон_стойност = 10;
    while (*низ_данни >= '0' && *низ_данни <= '9' && *низ_данни - '0' < Фон_стойност) {
        unsigned цифра_стойност = *низ_данни++ - '0'; 하나라도 = 1;
        if (стойност > (0x7ffffffffffffffful - цифра_стойност) / (unsigned)Фон_стойност) стойност = 0x7ffffffffffffffful;
        else стойност = стойност * Фон_стойност + цифра_стойност;
    }
    if (прекратяване_на_повикването_Изместване) *прекратяване_на_повикването_Изместване = (char *)(하나라도 ? низ_данни : Старт_Изместване); return кодиране_стойност > 0 ? (long)стойност : -(long)стойност;
}
int atoi(const char *низ_данни) { return (int)strtol(низ_данни, 0, 10); }
